(function() {
    'use strict';

    class MSPEntryAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Entrada al Mundo';
            this.version = '1.1.0';

            this.MARKETS = {
                peru: { name: 'Peru', flag: '\ud83c\uddf5\ud83c\uddea', O: 8, L: 7, I: 6, instDist: 2, size: 1.2 },
                brazil: { name: 'Brazil', flag: '\ud83c\udde7\ud83c\uddf7', O: 7, L: 8, I: 7, instDist: 5, size: 3.5 },
                canada: { name: 'Canada', flag: '\ud83c\udde8\ud83c\udde6', O: 6, L: 7, I: 8, instDist: 6, size: 2.8 },
                australia: { name: 'Australia', flag: '\ud83c\udde6\ud83c\uddfa', O: 6, L: 8, I: 9, instDist: 7, size: 3.2 }
            };

            this.ENTRY_MODES = {
                export: { control: 1, commitment: 1, risk: 1, speed: 4, label_en: 'Export Only', label_es: 'Solo Exportar' },
                licensing: { control: 2, commitment: 2, risk: 2, speed: 4, label_en: 'Licensing / Franchising', label_es: 'Licencia / Franquicia' },
                jv: { control: 3, commitment: 3, risk: 3, speed: 3, label_en: 'Joint Venture / Alliance', label_es: 'Joint Venture / Alianza' },
                wos_greenfield: { control: 5, commitment: 5, risk: 4, speed: 1, label_en: 'WOS Greenfield', label_es: 'Filial Propia Greenfield' },
                wos_acquisition: { control: 5, commitment: 5, risk: 3, speed: 3, label_en: 'WOS Acquisition', label_es: 'Filial Propia Adquisición' },
                branch: { control: 2, commitment: 1, risk: 1, speed: 5, label_en: 'Branch / Representative Office', label_es: 'Sucursal / Oficina' },
                alliance_rd: { control: 2, commitment: 2, risk: 2, speed: 3, label_en: 'R&D Strategic Alliance', label_es: 'Alianza Estratégica I+D' }
            };

            this.ROUNDS = [
                {
                    title_en: 'Round 1: Peru and Brazil Entry Design',
                    title_es: 'Ronda 1: Entrada a Perú y Brasil',
                    briefing_en: '<b>Year 1 — Launching the International Expansion</b><br><br>MSP Board has approved CLP 18.5B for a 5-year international expansion. You must now design entry strategies for the first two target markets: <b>Peru</b> (adjacent market, existing representative office in Lima) and <b>Brazil</b> (large iron ore/lithium market, complex regulatory environment). Consider the OLI framework: MSP has strong Ownership advantages (OrePlan Pro, 4-year technology lead, 3 patents), varying Location advantages by market, and critical Internalization considerations for proprietary technology.<br><br>Allocate the Year 1 budget (CLP 3.8B) across both markets. Your choices here will create learning effects and resource constraints that affect future rounds.',
                    briefing_es: '<b>Año 1 — Lanzamiento de la Expansión Internacional</b><br><br>El Directorio de MSP ha aprobado CLP 18.5B para un plan de expansión internacional a 5 años. Deben diseñar estrategias de entrada para los dos primeros mercados objetivo: <b>Perú</b> (mercado adyacente, oficina de representación existente en Lima) y <b>Brasil</b> (gran mercado de mineral de hierro/litio, entorno regulatorio complejo). Consideren el marco OLI: MSP tiene fuertes ventajas de Propiedad (OrePlan Pro, 4 años de ventaja tecnológica, 3 patentes), ventajas de Localización variables por mercado, y consideraciones críticas de Internalización para tecnología propietaria.<br><br>Asignen el presupuesto del Año 1 (CLP 3.8B) entre ambos mercados.'
                },
                {
                    title_en: 'Round 2: Learning Integration and Canada Entry',
                    title_es: 'Ronda 2: Integración de Aprendizaje y Entrada a Canadá',
                    briefing_en: '<b>18-Month Update</b><br><br>Peru operations are performing above expectations. OrePlan Pro has gained 12 new licenses in Peru. Brazil presents more challenges than anticipated — relationship-based market penetration is slower, and regulatory complexity is higher than modeled.<br><br>Now design your Canada entry strategy. Options include licensing OrePlan Pro to a Canadian distributor, WOS greenfield in Vancouver/Calgary, acquisition of TerraMap Systems Inc. (CLP 28B, a Canadian mine planning software firm), or an R&D alliance with UBC Keevil Institute.<br><br>Intelligence reports suggest Rio Pacific Ltd. (Australian incumbent) is evaluating LATAM expansion. Consider investing CLP 0.4B in competitive intelligence.',
                    briefing_es: '<b>Actualización de 18 Meses</b><br><br>Las operaciones en Perú superan las expectativas. OrePlan Pro ha ganado 12 nuevas licencias en Perú. Brasil presenta más desafíos de lo anticipado — la penetración de mercado basada en relaciones es más lenta, y la complejidad regulatoria es mayor de lo modelado.<br><br>Diseñen su estrategia de entrada a Canadá. Las opciones incluyen licenciar OrePlan Pro a un distribuidor canadiense, filial propia greenfield en Vancouver/Calgary, adquisición de TerraMap Systems Inc. (CLP 28B), o una alianza de I+D con UBC Keevil Institute.<br><br>Informes de inteligencia sugieren que Rio Pacific Ltd. está evaluando expandirse a LATAM. Consideren invertir CLP 0.4B en inteligencia competitiva.'
                },
                {
                    title_en: 'Round 3: Australia Entry and Competitive Response',
                    title_es: 'Ronda 3: Entrada a Australia y Respuesta Competitiva',
                    briefing_en: '<b>Year 2.5 — The Global Competitive Game</b><br><br>Rio Pacific Ltd. has announced a strategic review of LATAM mining services opportunities. Your Australia entry directly affects the competitive dynamics of your home market. Remember: in mining services, where major projects are global tenders, entering Australia creates direct competitive exposure with Rio Pacific in future LATAM tenders.<br><br>Choose your Australia entry mode, timing strategy, and competitive response to Rio Pacific. This is not just a market access decision — it is a global competitive strategy decision.',
                    briefing_es: '<b>Año 2.5 — El Juego Competitivo Global</b><br><br>Rio Pacific Ltd. ha anunciado una revisión estratégica de oportunidades de servicios mineros en LATAM. Su entrada a Australia afecta directamente la dinámica competitiva de su mercado local. Recuerden: en servicios mineros, donde los grandes proyectos son licitaciones globales, entrar a Australia crea exposición competitiva directa con Rio Pacific en futuras licitaciones LATAM.<br><br>Elijan su modo de entrada a Australia, estrategia de timing, y respuesta competitiva a Rio Pacific.'
                },
                {
                    title_en: 'Round 4: Portfolio Optimization and Strategic Architecture',
                    title_es: 'Ronda 4: Optimización del Portafolio y Arquitectura Estratégica',
                    briefing_en: '<b>Year 3 — Strategic Architecture Review</b><br><br>MSP now operates in 2-4 international markets with varying degrees of success. Review each market against the original OLI assessment: should you deepen commitment, maintain current operations, restructure the entry mode, or exit?<br><br>As MSP has evolved from a domestic company to a multilatina with advanced market presence, choose the organizational structure that best supports your international portfolio. Apply the logic of structural fit: does your mix of WOS, JV, and licensing arrangements require a Global Product Division, Geographic Area Structure, International Division, or Matrix organization?',
                    briefing_es: '<b>Año 3 — Revisión de Arquitectura Estratégica</b><br><br>MSP ahora opera en 2-4 mercados internacionales con diferentes grados de éxito. Revisen cada mercado contra la evaluación OLI original: ¿deben profundizar, mantener, reestructurar el modo de entrada, o salir?<br><br>A medida que MSP ha evolucionado de empresa doméstica a multilatina con presencia en mercados avanzados, elijan la estructura organizacional que mejor soporte su portafolio internacional.'
                }
            ];

            this.RANDOM_EVENTS = [
                [
                    { prob: 0.25, text_en: 'Peru introduces new Ley General de Minería restricting foreign service contractors. WOS compliance cost increases; JV becomes more attractive.', text_es: 'Perú introduce nueva Ley General de Minería restringiendo contratistas extranjeros. El costo de cumplimiento de filial propia aumenta; JV se vuelve más atractivo.', effect: 'peru_regulation' }
                ],
                [
                    { prob: 0.40, text_en: 'Brazilian JV partner files competing patent on OrePlan Pro interface adaptation. IP dispute forces course correction.', text_es: 'El socio de JV brasileño presenta patente competitiva sobre la adaptación de la interfaz de OrePlan Pro. La disputa de PI fuerza corrección.', effect: 'brazil_ip_dispute', condition: 'brazil_jv' },
                    { prob: 0.30, text_en: 'Copper price drops 22% due to China demand shock. Chilean mining capex deferred 18 months. International diversification urgency increases.', text_es: 'El precio del cobre cae 22% por shock de demanda china. Capex minero chileno diferido 18 meses. Aumenta urgencia de diversificación internacional.', effect: 'copper_crash' },
                    { prob: 0.25, text_en: 'Canadian government mineral technology tax credit covers 35% of WOS establishment cost. Greenfield becomes significantly more attractive.', text_es: 'Crédito fiscal del gobierno canadiense para tecnología mineral cubre 35% del costo de establecimiento de filial propia. Greenfield se vuelve significativamente más atractivo.', effect: 'canada_tax_credit' }
                ],
                [
                    { prob: 0.35, text_en: 'Rio Pacific Ltd. acquires a Peruvian mining services company, entering LATAM directly. Competitive threat is now concrete.', text_es: 'Rio Pacific Ltd. adquiere una empresa peruana de servicios mineros, entrando directamente a LATAM. La amenaza competitiva es ahora concreta.', effect: 'rio_latam_entry' },
                    { prob: 0.20, text_en: 'Australian regulator AMMA requires foreign mining equipment operators to meet AS 4600 standards. WOS greenfield entry becomes harder; alliance or acquisition preferred.', text_es: 'El regulador australiano AMMA exige que operadores extranjeros de equipos mineros cumplan con estándares AS 4600. La entrada greenfield se dificulta; se prefiere alianza o adquisición.', effect: 'australia_regulation' }
                ],
                [
                    { prob: 0.30, text_en: 'CODELCO announces evaluation of OrePlan Pro as Chilean national mining standard. IP value amplified; licensing negotiation leverage increases globally.', text_es: 'CODELCO anuncia evaluación de OrePlan Pro como estándar nacional minero chileno. El valor de PI se amplifica; aumenta el apalancamiento de negociación de licencias globalmente.', effect: 'codelco_standard' }
                ]
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 18.5,
                    budgetSpent: 0,
                    portfolioIRR: 0,
                    totalLicenses: 67,
                    ipScore: 100,
                    gcpi: 50,
                    marketPenetration: 0,
                    peruMode: '',
                    brazilMode: '',
                    canadaMode: '',
                    australiaMode: '',
                    peruBudget: 0,
                    brazilBudget: 0,
                    peruPenetration: 0,
                    brazilPenetration: 0,
                    canadaPenetration: 0,
                    australiaPenetration: 0,
                    brazilCorrection: '',
                    canadaGovernance: '',
                    competIntel: false,
                    australiaTiming: '',
                    rioResponse: '',
                    portfolioReview: {},
                    orgArchitecture: '',
                    irrHistory: [],
                    licensesHistory: [],
                    gcpiHistory: [],
                    activeEvents: [],
                    capabilityScore: 0,
                    rioLatamShare: 5,
                    copperCrash: false,
                    canadaTaxCredit: false,
                    codelcoStandard: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primary: '',
                    secondary: '',
                    tertiary: '',
                    quaternary: '',
                    budgetAlloc: 1.9
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && window.mySimulation.currentLanguage) || 'en';
            var ds = state.domainState || {};

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefing_es : round.briefing_en;
            }

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                var roundEvents = ds.activeEvents || [];
                var currentRoundEvents = roundEvents.filter(function(e) { return e.round === idx; });
                if (currentRoundEvents.length > 0) {
                    eventPanel.style.display = 'block';
                    var evHtml = '';
                    for (var ei = 0; ei < currentRoundEvents.length; ei++) {
                        evHtml += (lang === 'es' ? currentRoundEvents[ei].text_es : currentRoundEvents[ei].text_en);
                        if (ei < currentRoundEvents.length - 1) evHtml += '<br><br>';
                    }
                    eventText.innerHTML = evHtml;
                } else {
                    eventPanel.style.display = 'none';
                }
            }

            var dynPanel = document.getElementById('dynamicDecisions');
            if (!dynPanel) return;

            var period = state.currentPeriod || 1;

            // v1.1.0 FIX: once the simulation is complete (period beyond the last
            // round) do not render a stale, editable-looking decision panel behind
            // the completion modal. Hide decisions and just refresh the market grid.
            var _maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            if (period > _maxP) {
                dynPanel.innerHTML = '';
                var _decPanel = document.getElementById('decisionsPanel');
                if (_decPanel) _decPanel.style.display = 'none';
                this._updateMarketGrid(ds, lang);
                return;
            }

            var html = '';

            if (period === 1) {
                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="peru_mode_label">' + (lang === 'es' ? 'Modo de Entrada a Perú' : 'Peru Entry Mode') + '</label>';
                html += '<select id="primaryInput">';
                html += '<option value="branch">' + (lang === 'es' ? 'Expandir oficina a sucursal (bajo compromiso)' : 'Expand office to branch (low commitment)') + '</option>';
                html += '<option value="wos_greenfield">' + (lang === 'es' ? 'Filial propia - Greenfield' : 'WOS - Greenfield') + '</option>';
                html += '<option value="jv">' + (lang === 'es' ? 'JV con Ferreycorp S.A.C.' : 'JV with Ferreycorp S.A.C.') + '</option>';
                html += '<option value="licensing">' + (lang === 'es' ? 'Licencia de OrePlan Pro solamente' : 'OrePlan Pro licensing only') + '</option>';
                html += '</select></div>';

                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="brazil_mode_label">' + (lang === 'es' ? 'Modo de Entrada a Brasil' : 'Brazil Entry Mode') + '</label>';
                html += '<select id="secondaryInput">';
                html += '<option value="export">' + (lang === 'es' ? 'Solo exportación (sin presencia local)' : 'Export only (no local presence)') + '</option>';
                html += '<option value="licensing">' + (lang === 'es' ? 'Agente/Distribuidor local' : 'Agent/Distributor agreement') + '</option>';
                html += '<option value="jv">' + (lang === 'es' ? 'JV minoritario con Serviços Minerais do Brasil' : 'Minority JV with Serviços Minerais do Brasil') + '</option>';
                html += '<option value="wos_greenfield">' + (lang === 'es' ? 'Filial propia greenfield en Pará' : 'Greenfield WOS in Pará') + '</option>';
                html += '</select></div>';

                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="budget_alloc_label">' + (lang === 'es' ? 'Presupuesto Año 1 para Perú (CLP B) — resto va a Brasil. Total: 3.8B' : 'Year 1 Budget for Peru (CLP B) — remainder goes to Brazil. Total: 3.8B') + '</label>';
                html += '<input type="number" id="budgetInput" min="0.5" max="3.3" step="0.1" value="1.9">';
                html += '</div>';
            }

            if (period === 2) {
                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="brazil_correction_label">' + (lang === 'es' ? 'Corrección de Curso en Brasil' : 'Brazil Course Correction') + '</label>';
                html += '<select id="primaryInput">';
                if (ds.brazilMode === 'licensing' || ds.brazilMode === 'export') {
                    html += '<option value="upgrade_jv">' + (lang === 'es' ? 'Actualizar a JV' : 'Upgrade to JV') + '</option>';
                    html += '<option value="upgrade_wos">' + (lang === 'es' ? 'Actualizar a filial propia' : 'Upgrade to WOS') + '</option>';
                    html += '<option value="maintain">' + (lang === 'es' ? 'Mantener modo actual' : 'Maintain current mode') + '</option>';
                } else if (ds.brazilMode === 'jv') {
                    html += '<option value="escalate_legal">' + (lang === 'es' ? 'Escalar disputa de PI (legal)' : 'Escalate IP dispute (legal)') + '</option>';
                    html += '<option value="renegotiate">' + (lang === 'es' ? 'Renegociar términos del JV' : 'Renegotiate JV terms') + '</option>';
                    html += '<option value="convert_wos">' + (lang === 'es' ? 'Convertir a filial propia' : 'Convert to WOS') + '</option>';
                } else {
                    html += '<option value="accelerate">' + (lang === 'es' ? 'Acelerar expansión' : 'Accelerate expansion') + '</option>';
                    html += '<option value="maintain">' + (lang === 'es' ? 'Mantener ritmo actual' : 'Maintain current pace') + '</option>';
                }
                html += '</select></div>';

                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="canada_mode_label">' + (lang === 'es' ? 'Modo de Entrada a Canadá' : 'Canada Entry Mode') + '</label>';
                html += '<select id="secondaryInput">';
                html += '<option value="licensing">' + (lang === 'es' ? 'Licenciar OrePlan Pro a distribuidor canadiense' : 'License OrePlan Pro to Canadian distributor') + '</option>';
                html += '<option value="wos_greenfield">' + (lang === 'es' ? 'Filial propia greenfield (Vancouver/Calgary)' : 'WOS Greenfield (Vancouver/Calgary)') + '</option>';
                html += '<option value="wos_acquisition">' + (lang === 'es' ? 'Adquisición de TerraMap Systems (CLP 28B)' : 'Acquire TerraMap Systems Inc. (CLP 28B)') + '</option>';
                html += '<option value="alliance_rd">' + (lang === 'es' ? 'Alianza I+D con UBC Keevil Institute' : 'R&D Alliance with UBC Keevil Institute') + '</option>';
                html += '</select></div>';

                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="compet_intel_label">' + (lang === 'es' ? 'Invertir CLP 0.4B en Inteligencia Competitiva sobre Rio Pacific' : 'Invest CLP 0.4B in Competitive Intelligence on Rio Pacific') + '</label>';
                html += '<select id="tertiaryInput">';
                html += '<option value="yes">' + (lang === 'es' ? 'Sí — invertir en inteligencia' : 'Yes — invest in intelligence') + '</option>';
                html += '<option value="no">' + (lang === 'es' ? 'No — conservar presupuesto' : 'No — conserve budget') + '</option>';
                html += '</select></div>';
            }

            if (period === 3) {
                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="australia_mode_label">' + (lang === 'es' ? 'Modo de Entrada a Australia' : 'Australia Entry Mode') + '</label>';
                html += '<select id="primaryInput">';
                html += '<option value="licensing">' + (lang === 'es' ? 'Licenciar OrePlan Pro a empresa australiana' : 'License OrePlan Pro to Australian company') + '</option>';
                html += '<option value="wos_greenfield">' + (lang === 'es' ? 'Filial propia greenfield en Perth' : 'WOS Greenfield in Perth') + '</option>';
